    "benefits.card.label1": "Benefício 1",
    "benefits.card.title1": "Pare de Perder Vendas Invisíveis",
    "benefits.card.desc1": "Anunciantes que migram para o trackeamento server-side da Ratoeira recuperam em média 25% a 40% de conversões que estavam invisíveis. Cada venda recuperada é lucro que você já tinha gerado — e que o pixel padrão estava escondendo do Google.",
    "benefits.card.label2": "Benefício 2",
    "benefits.card.title2": "Proteja Seu Orçamento no Google Ads",
    "benefits.card.desc2": "Para quem anuncia no Google Ads, a Ratoeira bloqueia automaticamente os IPs que clicam no seu anúncio sem intenção de comprar — concorrentes, bots, tráfego inválido. Na maioria das operações, a economia com bloqueio já cobre o custo do plano inteiro no primeiro mês.",
    "benefits.card.label3": "Benefício 3",
    "benefits.card.title3": "Publique Páginas em Minutos, Não Dias",
    "benefits.card.desc3": "Templates prontos e validados, Flash Pages que abrem em menos de 1 segundo e trackeamento automático desde o primeiro clique. Sua página no ar antes do próximo anúncio subir — e cada visita já rastreada.",
    "benefits.card.label4": "Benefício 4",
    "benefits.card.title4": "Tome Decisões Com Dados Reais, Não Intuição",
    "benefits.card.desc4": "Dashboard consolidado com métricas do Google Ads, Meta Ads e plataformas de vendas numa tela só. Você vê qual campanha escalar, qual pausar — e age antes que o algoritmo tome a decisão errada por você.",
    "benefits.card.label5": "Benefício 5",
    "benefits.card.title5": "Acompanhe De Qualquer Lugar",
    "benefits.card.desc5": "App próprio para iOS e Android. Notificação de venda em tempo real, acompanhamento de campanhas e alertas de bloqueio — onde quer que você esteja. A operação na palma da mão.",
    "benefits.card.label6": "Benefício 6",
    "benefits.card.title6": "Risco Zero",
    "benefits.card.desc6": "Garantia incondicional de 7 dias. Se não gostar, devolvemos 100%. Sem perguntas, sem burocracia. Você não tem nada a perder.",

