    "problem.header.title4": "Em um só",
    "problem.header.title5": "lugar",
    "problem.header.subtitle": "Quem escala no Google e no Meta não usa ferramentas soltas. Usa um ecossistema onde trackeamento, páginas e dados conversam entre si — e cada real investido tem uma origem rastreada. Operações que migram para o Hub reportam aumento de lucro em até 60%.",
