    "problem.tabs.tracking": "Rastreamento Inteligente",
    "problem.tabs.pages": "Páginas de Alta Conversão",
    "problem.tabs.ecossystem": "Ratoeira Hub",
    "problem.tracking.title": "Rastreie cada venda. Bloqueie cada fraude. Decida mais rápido.",
    "problem.tracking.description": "O pixel padrão desperdiça entre 25% e 40% das suas vendas — elas acontecem, mas o Google nunca fica sabendo. A Ratoeira usa a tecnologia de trackeamento server-side mais avançada disponível hoje, com envio via browser e API simultaneamente, chegando a ~100% de conversões rastreadas. O algoritmo passa a otimizar para quem realmente compra — e o lucro sobe.\n\nPara quem anuncia no Google Ads: a Ratoeira identifica e bloqueia automaticamente os IPs que clicam no seu anúncio sem intenção de comprar — concorrentes, bots, tráfego inválido. Na maioria das operações, o que você economiza com bloqueio já cobre o custo do plano inteiro no primeiro mês.",
    "problem.tracking.highlight1": "Trackeamento server-side com ~100% de conversões rastreadas",
    "problem.tracking.highlight2": "Bloqueio automático de bots e IPs fraudulentos",
    "problem.tracking.highlight3": "Dashboard consolidado: Google Ads + Plataformas + Anti-Fraude",
    "problem.tracking.highlight4": "+60 plataformas de vendas conectadas",
    "problem.tracking.highlight5": "Notificações em tempo real via app e Telegram",
    "problem.tracking.alt": "Rastreamento Inteligente",
    "problem.pages.title": "Construa páginas que vendem em minutos. Sem código.",
    "problem.pages.description": "A Ratoeira Pages é o construtor nativo do ecossistema. Templates prontos e validados, Flash Pages que abrem em menos de 1 segundo, criação por IA com 1 clique e hospedagem inclusa. O diferencial: cada página já nasce com o trackeamento integrado — zero configuração, zero dado perdido entre a página e a campanha.",
    "problem.pages.highlight1": "Templates prontos e testados para conversão",
    "problem.pages.highlight2": "Editor visual drag-and-drop (sem código)",
    "problem.pages.highlight3": "Flash Pages: páginas prontas em segundos",
    "problem.pages.highlight4": "Geração de páginas por IA",
    "problem.pages.highlight5": "Hospedagem gratuita com SSL e domínios customizados",
    "problem.pages.highlight6": "Integração nativa com o Ratoeira Ads",
    "problem.pages.alt": "Páginas de Alta Conversão",
    "problem.ecossystem.title": "Ads + Pages juntos. Um login. Zero fricção.",
    "problem.ecossystem.description": "O verdadeiro poder da Ratoeira está na integração nativa. Quando o Ads e o Pages operam juntos, o trackeamento vai além do que cada produto entrega separado — porque o dado da página alimenta a campanha em tempo real. Enquanto outros anunciantes operam com três ou mais ferramentas que não conversam entre si, você tem tudo consolidado num único dashboard. Um login. Zero fricção. Resultado máximo.",
