    "faq.cta.subtitle": "Nossa equipe de especialistas está pronta para ajudar você a escalar suas operações com segurança.",
    "faq.cta.button": "Falar com Suporte",
    "faq.q1.question": "O que é o Ratoeira Ads?",
    "faq.q1.answer": "O Ratoeira Ads é a plataforma definitiva para escalar suas operações de tráfego pago. Combina ferramentas de tracking avançado com proteção contra fraudes em um único dashboard para garantir máxima conversão.",
    "faq.q2.question": "Como funciona a proteção contra fraudes?",
    "faq.q2.answer": "Nossa tecnologia utiliza algoritmos de inteligência artificial e bloqueio de IPs dinâmicos em tempo real para identificar e barrar tráfego de bots, cliques fraudulentos e agentes mal-intencionados antes que eles consumam seu orçamento.",
    "faq.q3.question": "Posso usar meus próprios domínios?",
    "faq.q3.answer": "Sim! Dependendo do seu plano, você pode conectar de 1 a ilimitados domínios customizados, mantendo a identidade visual da sua marca enquanto aproveita toda a nossa infraestrutura de rastreamento server-side.",
    "faq.q4.question": "Qual a diferença entre os planos Mensal e Anual?",
    "faq.q4.answer": "Ao optar pelo plano Anual, além de garantir o acesso ininterrupto à plataforma por 12 meses, você ganha um desconto exclusivo de 20% no valor total. Todos os recursos do plano escolhido permanecem os mesmos independentemente do ciclo de faturamento.",
    "faq.q5.question": "O Ratoeira Ads tem período de teste ou garantia?",
    "faq.q5.answer": "Sim, você está protegido por nossa garantia incondicional de 14 dias (conforme o CDC). Se dentro desse período você achar que a plataforma não atende às suas necessidades, basta solicitar o cancelamento e devolvemos 100% do seu dinheiro.",
    "faq.q6.question": "Preciso de conhecimento técnico para configurar o tracking?",
    "faq.q6.answer": "Não! Desenvolvemos o Ratoeira Ads com foco na facilidade de uso. Nossas integrações nativas permitem conectar o Ratoeira Ads às principais fontes de tráfego (Google, Meta, etc.) e gateways de pagamento com apenas alguns cliques.",

