    // About
    "about.title": "Quem Somos",
    "about.subtitle": "Conheça a Ratoeira Hub",

    // About Hero
    "about.hero.badge": "NOSSA HISTÓRIA",
    "about.hero.title": "nasceu de dentro do mercado. Não de fora.",
    "about.hero.paragraph1": "Em dezembro de 2022, Eitor Guimarães anunciava como afiliado de Google Ads e aplicava o que sabia de analytics corporativo a um problema que o mercado brasileiro ainda não havia resolvido: como capturar os dados do clique, cruzar com a conversão e devolver esse sinal limpo ao algoritmo do Google para ele otimizar para quem realmente compra. Ferramentas gringas faziam isso — e não afetavam. Chegavam a custar R$1.000 por mês e ainda assim não entendiam o ecossistema brasileiro de afiliados.",
    "about.hero.paragraph2": "Eitor sistematizou o método e publicou um vídeo no YouTube em outubro de 2023. Explodiu. O mercado de afiliados de Google Ads mudou de patamar: operações que antes travavam em só a R$100 mil passaram a escalar além de um milhão. Em janeiro de 2024, Paulo Furtado viu o vídeo e foi direto ao Instagram de Eitor propor construir o software. Em 15 de abril de 2024, a Ratoeira Ads entrava no ar. Hoje, mais de 2.500 anunciantes são assinantes ativos — e mais de 10.000 já passaram pela plataforma.",

    // About Timeline
    "about.timeline.header": "Dois anos. O <span class='text-[#FFB800]'>mercado</span> não é mais o <span class='text-[#FFB800]'>mesmo</span>",
    "about.timeline.subtitle": "De uma descoberta individual a mais de 2.500 anunciantes que escalam com dado real.",
    "about.timeline.discovery": "A Descoberta",
    "about.timeline.discoveryDesc": "Em dezembro de 2022, Eitor começa a aplicar métodos de analytics corporativo ao mercado de afiliados brasileiro, identificando o gap de dados entre cliques e conversões.",
    "about.timeline.method": "O mercado descobre o método",
    "about.timeline.methodDesc": "Outubro de 2023: Eitor publica o primeiro vídeo explicando o método. O conteúdo viraliza e muda o patamar de operações de Google Ads no Brasil.",
    "about.timeline.meeting": "Paulo encontra Eitor",
    "about.timeline.meetingDesc": "Janeiro de 2024: Paulo Furtado vê o vídeo e propõe a Eitor construir o software que sistematizaria o método.",
    "about.timeline.launch": "Ratoeira Ads vai ao ar",
    "about.timeline.launchDesc": "15 de abril de 2024: Ratoeira Ads entra no ar com a missão de democratizar o rastreamento server-side para o mercado brasileiro.",
    "about.timeline.expansion": "Expansão do ecossistema",
    "about.timeline.expansionDesc": "Ratoeira Pages e Ratoeira Hub são lançados, integrando construção de páginas e dashboard consolidado ao ecossistema.",
    "about.timeline.ai": "IA e novos canais",
    "about.timeline.aiDesc": "A plataforma incorpora inteligência artificial e expandsion para Meta Ads, Native Ads e novas fontes de tráfego.",

