    // About Platform CTA
    "about.platform.title": "Somos o ecossistema <span class='text-transparent bg-clip-text bg-gradient-to-r from-orange-600 to-amber-500'>definitivo</span> para escala.",
    "about.platform.description": "Projetamos a <span class='whitespace-nowrap'>Ratoeira Hub</span> para aniquilar o desperdício de verba e a complexidade técnica. Oferecemos uma solução segura, rápida e abrangente que une rastreamento cirúrgico e páginas de altíssima conversão em um único lugar.",

    // About MVV
    "about.mvv.mission": "Missão",
    "about.mvv.missionDesc": "Democratizar o acesso a dados limpos e decisões inteligentes no tráfego pago, para que qualquer anunciante — do iniciante ao gestor profissional — possa escalar com previsibilidade.",
    "about.mvv.vision": "Visão",
    "about.mvv.visionDesc": "Ser o ecossistema de referência em rastreamento e otimização de tráfego pago para o mercado latino-americano, impactar 100.000 operações até 2027.",
    "about.mvv.values": "Valores",
    "about.mvv.values.title1": "Mudar vidas",
    "about.mvv.values.title2": "Cliente é o motivo",
    "about.mvv.values.title3": "Ser os melhores naquilo que fazemos",
    "about.mvv.values.title4": "A verdade, sempre",
    "about.mvv.values.title5": "Inovar é sobreviver",
    "about.mvv.values.item1": "Dados antes de achismo: toda decisão é respaldada por dado real.",
    "about.mvv.values.item2": "Simplicidade: tecnologia avançada, uso simples.",
    "about.mvv.values.item3": "Transparência: preços claros, sem letras miúdas.",
    "about.mvv.values.item4": "Evolução constante: o mercado muda, a Ratoeira muda com ele.",
    "about.mvv.values.item5": "Inovar é sobreviver: o mundo do tráfego pago muda rápido. Buscar novas formas de resolver o mesmo problema não é diferencial — é sobrevivência.",

    // About Founders
    "about.founders.founder1": "Eitor Guimarães",
    "about.founders.role1": "Co-fundador & CEO",
    "about.founders.founder2": "Paulo Furtado",
    "about.founders.role2": "Co-fundador & CTO",
    "about.founders.founder3": "Brayan Cicarone",
    "about.founders.role3": "Co-fundador & Líder de Desenvolvimento - Ratoeira Pages",
    "about.founders.header": "Três pessoas. Um problema real. Uma plataforma",
    "about.founders.headerSubtitle": "As mentes por trás do ecossistema que está revolucionando o tráfego pago.",
    "about.founders.three": "Três",
    "about.founders.people": "pessoas. Um",
    "about.founders.problem": "problema",
    "about.founders.real": "real.",
    "about.founders.solution": "plataforma",
    "about.founders.subtitle": "As mentes por trás do ecossistema que está revolucionando o tráfego pago.",
    "about.founders.eitorDesc": "Formado pela UNICAMP, Eitor construiu sua carreira em analytics e inteligência de mercado — passando por 3M e PepsiCo, onde liderou times de Business Intelligence e Data & Analytics para a América Latina. Em 2022, levou esse repertório para o tráfego pago e sistematizou, de forma pioneira no Brasil, o que o mercado de afiliados de Google Ads ainda não tinha: trackeamento server-side para que o Google Ads otimize para compradores reais. O método mudou o patamar do mercado — operações que travavam em até R$100 mil passaram a escalar além de um milhão. Em abril de 2024, junto com Paulo, transformou a descoberta em produto. Hoje lidera a Ratoeira como CEO.",
    "about.founders.pauloDesc": "Formado em análise de sistemas em 2012, Paulo passou mais de uma década construindo sistemas robustos — incluindo passagem pela Localiza. Em janeiro de 2024, assistiu ao vídeo de Eitor sobre trackeamento para afiliados de Google Ads e enxergou o produto que ainda não existia. Foi direto ao Instagram propor a parceria. Como CTO da Ratoeira, Paulo é responsável pela arquitetura que garante trackeamento ~100%, processamento de eventos em tempo real e as integrações via API com Google Ads, Meta e plataformas de IA.",
    "about.founders.brayanDesc1": "Especialista em arquitetura de software e MBA em Banco de Dados, Brayan construiu sua trajetória atuando no desenvolvimento de sistemas, arquitetura de software e produtos digitais. Em 2025, passou a colaborar com Paulo e Eitor na evolução da Ratoeira Ads, ajudando a resolver desafios técnicos e a estruturar novas soluções para o mercado.",
    "about.founders.brayanDesc2": "Ao participar desse processo, enxergou a necessidade de uma plataforma que simplificasse a criação de páginas e integrações para anunciantes. Dessa visão nasceu a Ratoeira Pages. Hoje, é responsável pela arquitetura da plataforma, pelas integrações com inteligência artificial e pela construção das ferramentas que impulsionam a próxima fase do ecossistema Ratoeira.",

