    "parcerias.benefits.desc1": "Enquanto seu indicado usar a Ratoeira, você recebe comissão recorrente sobre o valor da assinatura todos os meses. Comece em 10% e evolua conforme o número de indicados ativos.",
    "parcerias.benefits.desc2": "Indique uma solução que resolve a maior dor do mercado: bloqueios e perda de ROI. O Ratoeira Hub tem altíssima taxa de retenção.",
