    "privacidade.pages.section6.p1": "As informações são armazenadas em servidores seguros com criptografia, firewalls e medidas técnicas e organizacionais razoáveis de proteção. A RATOEIRA PAGES adota medidas rigorosas contra perda, roubo ou acesso não autorizado.",
