    "privacidade.pages.section6.p3": "Os registros de log de sistema, incluindo ações dos usuários e padrões de comportamento na plataforma, serão mantidos por prazo mínimo de 5 (cinco) anos, contados a partir do registro, em conformidade com o Marco Civil da Internet (Lei nº 12.965/2014) e a LGPD, podendo ser utilizados como meio de prova em qualquer procedimento judicial, administrativo ou arbitral.",
    "privacidade.pages.section6.p4": "Os dados de cadastro são mantidos enquanto o usuário estiver ativo na plataforma, podendo ser guardados por período adicional para cumprimento de obrigações legais.",
    "privacidade.pages.section7.title": "Uso de Inteligência Artificial",
    "privacidade.pages.section7.p1": "A Plataforma RATOEIRA PAGES utiliza recursos de Inteligência Artificial (IA) para geração e revisão automatizada de páginas. Esses recursos operam a partir de dados e briefing fornecidos pelo Usuário e de modelos algorítmicos de terceiros (incluindo OpenAI).",
    "privacidade.pages.section7.p2": "A RATOEIRA PAGES não garante exatidão, completude, originalidade, ausência de vieses ou conformidade do conteúdo gerado por IA com políticas de terceiros. É dever exclusivo do Usuário revisar, aprovar e assumir responsabilidade pelo conteúdo antes de sua publicação.",
    "privacidade.pages.section7.p3": "Os dados fornecidos para geração de conteúdo por IA são processados de acordo com esta Política e com os termos dos provedores de serviços de IA utilizados.",
    "privacidade.pages.section8.title": "Cookies e Tecnologias de Rastreamento",
