    "cases.detail.operacao-alpha.challenge": "A Operação Alpha sofria com uma alta taxa de cliques inválidos e bots que consumiam rapidamente o orçamento diário no Google Ads. Além disso, a perda de dados de conversão pelo pixel padrão dificultava a otimização das campanhas, fazendo com que o CPA estivesse muito acima do aceitável.",
    "cases.detail.operacao-alpha.solution": "Ao integrar o Ratoeira Ads, a empresa passou a utilizar o tracking server-side, garantindo precisão quase absoluta nos eventos de conversão. O bloqueio dinâmico de IPs fraudulentos também foi ativado, protegendo o orçamento e focando apenas em usuários reais.",
    "cases.detail.operacao-alpha.testimonial": "O Ratoeira Hub não apenas salvou nosso caixa, mas nos deu a confiança necessária para triplicar nosso investimento em tráfego pago sem medo de perder dinheiro com bots.",
    "cases.detail.agencia-vortex.name": "Agência Vortex",
