    "cases.detail.agencia-vortex.challenge": "Gerenciar landing pages para múltiplos clientes era um pesadelo logístico. As páginas desenvolvidas em plataformas tradicionais demoravam para carregar, e o setup de rastreamento avançado tomava dias da equipe técnica para cada novo lançamento.",
    "cases.detail.agencia-vortex.solution": "A Agência Vortex migrou todas as suas operações para o Ratoeira Pages. Com templates focados em conversão e rastreamento nativo já embutido em cada nova página, a equipe reduziu o tempo de deploy de dias para apenas algumas horas.",
    "cases.detail.agencia-vortex.testimonial": "Nossa operação ficou muito mais enxuta e rápida. Nossos clientes sentiram o impacto na taxa de conversão quase imediatamente devido à velocidade das Flash Pages.",
    "cases.detail.metodo-escala.name": "Método Escala",
    "cases.detail.metodo-escala.role": "Anunciante Top Player",
    "cases.detail.metodo-escala.results.0": "~100% Tracking",
    "cases.detail.metodo-escala.results.1": "Setup em 1 Clique",
