    "cases.detail.metodo-escala.challenge": "A dependência de múltiplas ferramentas desconexas causava divergências constantes nos relatórios. O anunciante não sabia exatamente qual anúncio gerava vendas reais, o que impedia uma escala agressiva e segura das ofertas no Meta e no Google.",
    "cases.detail.metodo-escala.solution": "A adoção do Ratoeira Hub unificou a criação de páginas e o tracking server-side. Com um dashboard único exibindo o ROI real cruzado com as vendas aprovadas, o Método Escala passou a escalar com dados 100% precisos e confiáveis.",
    "cases.detail.metodo-escala.testimonial": "Parei de operar às cegas. Hoje, cada centavo investido é rastreado, validado e otimizado para gerar lucro de verdade. Foi a melhor decisão que já tomei para a minha operação.",

