    // Ratoeira Ads - FeaturesAds
    "ratoeiraAds.features.title": "O fim do achismo no tráfego pago.",
    "ratoeiraAds.features.subtitle": "A Ratoeira Ads atua em 6 frentes para garantir que você saiba exatamente qual anúncio do Google Ads gerou cada centavo de resultado — do clique à venda.",
    "ratoeiraAds.features.serverSide.title": "Tracking Server-Side",
    "ratoeiraAds.features.serverSide.desc": "Seus dados não dependem mais de cookies ou do pixel no navegador. A Ratoeira envia as conversões direto para a API de Conversões do Google — server-side, com envio enriquecido. O que o pixel padrão perde entre 25% e 40% das vezes, a Ratoeira registra. Mais conversões reais chegando ao Google Ads significa algoritmo otimizando para quem realmente compra.",
    "ratoeiraAds.features.ipBlocking.title": "Bloqueio Automático de IP",
    "ratoeiraAds.features.ipBlocking.desc": "Exclusivo para Google Ads. Você define o limite de cliques aceitos por IP — a Ratoeira bloqueia automaticamente quem ultrapassa. Concorrentes que clicam nos seus anúncios, tráfego inválido e bots são eliminados antes de consumir seu orçamento. Na maioria dos casos, o que você economiza já paga o plano inteiro.",
    "ratoeiraAds.features.conversions.title": "Conversões Otimizadas com Dado Enriquecido",
    "ratoeiraAds.features.conversions.desc": "A Ratoeira não envia só o evento — envia o sinal enriquecido. Com dados primários tratados e protegidos (como e-mail e telefone) enviados pela API de Conversões, o Google casa mais vendas ao clique que as gerou. O Smart Bidding passa a aprender com dado real, encontra mais pessoas parecidas com seus melhores compradores e o custo por aquisição cai enquanto o ROAS sobe.",
    "ratoeiraAds.features.invisible.title": "Recuperação de Conversões Invisíveis",
    "ratoeiraAds.features.invisible.desc": "Anunciantes que migram para o trackeamento server-side da Ratoeira recuperam em média 25% a 40% de conversões que estavam invisíveis. Cada venda recuperada é lucro que você já tinha gerado — e não sabia. Com mais conversões chegando ao Google Ads, o algoritmo otimiza mais rápido e sua campanha escala com mais segurança.",
    "ratoeiraAds.features.realtime.title": "Dados em Tempo Real",
    "ratoeiraAds.features.realtime.desc": "O Google Ads demora para consolidar conversões — e nesse intervalo o algoritmo pode continuar otimizando para o público errado. A Ratoeira mostra seus dados integrados — visitas, leads e vendas — mais rápido do que o próprio painel do Google. Você vê o que está funcionando e age antes que o orçamento vá para o lugar errado.",
    "ratoeiraAds.features.funnel.title": "Funil Completo Visível",
    "ratoeiraAds.features.funnel.desc": "Enquanto outras ferramentas mostram apenas de onde vieram os cliques, a Ratoeira mostra de onde vieram as vendas — com visitas, leads e conversões integradas num só lugar. Mais dado real chegando ao Google Ads significa públicos melhores, lances mais inteligentes e um custo por aquisição que cai enquanto o lucro sobe.",
    "ratoeiraAds.features.manager.title": "Gerenciador Integrado",
    "ratoeiraAds.features.manager.desc": "Controle campanhas, orçamentos, anúncios e públicos do Google Ads direto pela Ratoeira. Você pausa, escala e ajusta sem precisar alternar entre abas nem abrir o Google Ads. Menos fricção, mais velocidade de execução e zero campanha esquecida rodando no vermelho.",
    "ratoeiraAds.features.dashboard.title": "Dashboard Consolidado",
    "ratoeiraAds.features.dashboard.desc": "Visualize tudo em um só lugar: impressões, cliques, CPC, CPL, ROAS, conversões e receita — métricas do Google Ads cruzadas com as suas plataformas de venda. Sem planilhas, sem importação manual. O dashboard que você sempre quis ter, mas nenhuma ferramenta sozinha entregava.",
    "ratoeiraAds.features.imagePlaceholder": "Espaço para Imagem/Mockup",

    // Ratoeira Ads - Hero
    "heroAds.badge": "Trackeamento ~100% para <span class='whitespace-nowrap'>Google Ads</span>",
    "heroAds.title": "Rastreamento <span class='text-[#E6A600]'>~100%</span>. <span class='text-[#E6A600]'>Anti-fraude automático.</span> Os dados que o Google Ads não te entrega sozinho.",
    "heroAds.subtitle": "Para anunciantes no <span class='whitespace-nowrap'>Google Ads</span> que precisam de clareza total — não de estimativas. Cada venda rastreada, cada fraude bloqueada, cada decisão tomada com dado real.",

    // Ratoeira Ads - App Section
    "heroAds.app.title": "Que tal uma ratoeira no seu <span class='text-brand-primary'>bolso</span>?",
    "heroAds.app.description": "Com o APP da <span class='whitespace-nowrap'>Ratoeira Ads</span>, você recebe as notificações e tem acesso ao seu Dashboard de vendas, tudo em tempo real.",
    "heroAds.app.notifications": "Notificações em tempo real",
