    "heroAds.cta.description": "Configure a <span class='text-brand-primary font-semibold whitespace-nowrap'>Ratoeira Ads</span> em minutos e descubra o ROI real das suas campanhas com trackeamento ~100% e proteção automática no <span class='whitespace-nowrap'>Google Ads</span>.",
    "heroAds.cta.button": "Assinar Agora — ver planos",
    "heroAds.cta.tutorial": "Confira nosso tutorial completo →",
    "heroAds.cta.radar.serverSide": "Server-Side",
