    // Hero
    "hero.title.sale": "Every sale has an origin.",
    "hero.title.highlight": "Ratoeira shows you which one.",
    "hero.subtitle": "Real operations report up to 60% profit increase when they start tracking with real data. Every click, every lead, every sale — origin tracked on Google and Meta, in real time.",
    "hero.cta.signNow": "Sign Now",
    "hero.cta.learnMore": "Learn more",
