    "hero.pages.subtitle": "Create fast, trackable pages in minutes. With templates, Flash Pages in under 1 second and AI in 1 click. Ratoeira tracking is already integrated — no conversion is lost.",
    "hero.pages.tabLabel": "Pages that Convert",

    // Buttons
    "button.signNow": "Sign Now",
    "button.contactSales": "Contact sales",
    "button.knowMore": "Know more",
    "button.access": "Access",
