    // Benefits
    "benefits.title": "Benefits",
    "benefits.subtitle": "Everything you need to scale",
    "benefits.card.label1": "Benefit 1",
    "benefits.card.title1": "Stop Losing Invisible Sales",
    "benefits.card.desc1": "Advertisers who migrate to Ratoeira's server-side tracking recover on average 25% to 40% of conversions that were invisible. Every recovered sale is profit you had already generated — and that the standard pixel was hiding from Google.",
    "benefits.card.label2": "Benefit 2",
    "benefits.card.title2": "Protect Your Google Ads Budget",
    "benefits.card.desc2": "For those advertising on Google Ads, Ratoeira automatically blocks IPs that click on your ad without intention to buy — competitors, bots, invalid traffic. In most operations, the savings from blocking already cover the entire plan cost in the first month.",
    "benefits.card.label3": "Benefit 3",
    "benefits.card.title3": "Publish Pages in Minutes, Not Days",
    "benefits.card.desc3": "Ready and validated templates, Flash Pages that open in under 1 second and automatic tracking from the first click. Your page live before the next ad goes up — and every visit already tracked.",
    "benefits.card.label4": "Benefit 4",
    "benefits.card.title4": "Make Decisions With Real Data, Not Intuition",
    "benefits.card.desc4": "Consolidated dashboard with Google Ads, Meta Ads and sales platform metrics on a single screen. You see which campaign to scale, which to pause — and act before the algorithm makes the wrong decision for you.",
    "benefits.card.label5": "Benefit 5",
    "benefits.card.title5": "Monitor From Anywhere",
    "benefits.card.desc5": "Own app for iOS and Android. Real-time sale notification, campaign monitoring and blocking alerts — wherever you are. The operation in the palm of your hand.",
    "benefits.card.label6": "Benefit 6",
    "benefits.card.title6": "Zero Risk",
    "benefits.card.desc6": "Unconditional 7-day guarantee. If you don't like it, we refund 100%. No questions, no bureaucracy. You have nothing to lose.",

