    "problem.tabs.ecossystem": "Ratoeira Hub",
    "problem.tracking.title": "Track every sale. Block every fraud. Decide faster.",
    "problem.tracking.description": "The standard pixel wastes between 25% and 40% of your sales — they happen, but Google never knows. Ratoeira uses the most advanced server-side tracking technology available today, with browser and API sending simultaneously, reaching ~100% of tracked conversions. The algorithm starts optimizing for who actually buys — and profit goes up.\n\nFor those advertising on Google Ads: Ratoeira identifies and automatically blocks IPs that click on your ad without intention to buy — competitors, bots, invalid traffic. In most operations, what you save from blocking already covers the entire plan cost in the first month.",
    "problem.tracking.highlight1": "Server-side tracking with ~100% tracked conversions",
    "problem.tracking.highlight2": "Automatic blocking of bots and fraudulent IPs",
    "problem.tracking.highlight3": "Consolidated dashboard: Google Ads + Platforms + Anti-Fraud",
    "problem.tracking.highlight4": "+60 connected sales platforms",
    "problem.tracking.highlight5": "Real-time notifications via app and Telegram",
    "problem.tracking.alt": "Smart Tracking",
    "problem.pages.title": "Build pages that sell in minutes. No code.",
    "problem.pages.description": "Ratoeira Pages is the native builder of the ecosystem. Ready and validated templates, Flash Pages that open in under 1 second, AI page generation with 1 click and hosting included. The differential: each page is born with integrated tracking — zero configuration, zero data lost between the page and the campaign.",
    "problem.pages.highlight1": "Templates ready and tested for conversion",
    "problem.pages.highlight2": "Visual drag-and-drop editor (no code)",
    "problem.pages.highlight3": "Flash Pages: pages ready in seconds",
    "problem.pages.highlight4": "AI page generation",
    "problem.pages.highlight5": "Free hosting with SSL and custom domains",
    "problem.pages.highlight6": "Native integration with Ratoeira Ads",
    "problem.pages.alt": "High Conversion Pages",
    "problem.ecossystem.title": "Ads + Pages together. One login. Zero friction.",
    "problem.ecossystem.description": "The real power of Ratoeira is in the native integration. When Ads and Pages operate together, tracking goes beyond what each product delivers separately — because the page data feeds the campaign in real time. While other advertisers operate with three or more tools that don't communicate with each other, you have everything consolidated in a single dashboard. One login. Zero friction. Maximum results.",
    "problem.ecossystem.highlight1": "Native Ads + Pages integration (no manual configuration)",
    "problem.ecossystem.highlight2": "Single dashboard with +50 consolidated metrics",
    "problem.ecossystem.highlight3": "Real ROAS calculated with confirmed sales",
    "problem.ecossystem.highlight4": "Traffic data + pages + sales on one screen",
    "problem.ecossystem.alt": "Ratoeira Hub",

