    // FAQ
    "faq.title": "Frequently Asked Questions",
    "faq.subtitle": "Get your answers",
    "faq.badge": "Help Center",
    "faq.hero.title": "How can we <span class='text-brand-primary'>help?</span>",
    "faq.hero.subtitle": "Find quick answers to the most common questions about Ratoeira Ads, our plans, and integrations.",
    "faq.cta.title": "Support hours",
    "faq.cta.subtitle": "Our team of specialists is ready to help you scale your operations safely.",
    "faq.cta.button": "Talk to Support",
    "faq.q1.question": "What is Ratoeira Ads?",
    "faq.q1.answer": "Ratoeira Ads is the ultimate platform to scale your paid traffic operations. It combines advanced tracking tools with fraud protection in a single dashboard to ensure maximum conversion.",
    "faq.q2.question": "How does fraud protection work?",
    "faq.q2.answer": "Our technology uses artificial intelligence algorithms and dynamic IP blocking in real time to identify and block bot traffic, fraudulent clicks, and malicious agents before they consume your budget.",
    "faq.q3.question": "Can I use my own domains?",
    "faq.q3.answer": "Yes! Depending on your plan, you can connect from 1 to unlimited custom domains, maintaining your brand's visual identity while taking advantage of our entire server-side tracking infrastructure.",
    "faq.q4.question": "What's the difference between Monthly and Annual plans?",
    "faq.q4.answer": "By choosing the Annual plan, besides guaranteeing uninterrupted access to the platform for 12 months, you get an exclusive 20% discount on the total price. All the features of your chosen plan remain the same regardless of the billing cycle.",
    "faq.q5.question": "Does Ratoeira Ads have a trial period or guarantee?",
    "faq.q5.answer": "Yes, you are protected by our unconditional 14-day guarantee (according to CDC). If within this period you feel the platform doesn't meet your needs, just request cancellation and we'll refund 100% of your money.",
    "faq.q6.question": "Do I need technical knowledge to set up tracking?",
    "faq.q6.answer": "No! We developed Ratoeira Ads focusing on ease of use. Our native integrations allow you to connect Ratoeira Ads to major traffic sources (Google, Meta, etc.) and payment gateways with just a few clicks.",

