    // About
    "about.title": "Who We Are",
    "about.subtitle": "Meet Ratoeira Hub",

    // About Hero
    "about.hero.badge": "OUR STORY",
    "about.hero.title": "was born from within the market. Not from outside.",
    "about.hero.paragraph1": "In December 2022, Eitor Guimarães was advertising as a Google Ads affiliate and applied what he knew about corporate analytics to a problem the Brazilian market hadn't yet solved: how to capture click data, cross-reference it with conversion, and return that clean signal to the Google algorithm so it could optimize for those who actually buy. Foreign tools did this — and didn't work. They cost up to R$1,000 per month and still didn't understand the Brazilian affiliate ecosystem.",
    "about.hero.paragraph2": "Eitor systematized the method and published a video on YouTube in October 2023. It exploded. The Google Ads affiliate market changed its level: operations that previously stalled at just R$100 thousand scaled to over a million. In January 2024, Paulo Furtado saw the video and went directly to Eitor's Instagram to propose building the software. On April 15, 2024, Ratoeira Ads went live. Today, more than 2,500 advertisers are active subscribers — and more than 10,000 have already been through the platform.",

    // About Timeline
    "about.timeline.header": "Two years. The <span class='text-[#FFB800]'>market</span> is no longer the <span class='text-[#FFB800]'>same</span>",
    "about.timeline.subtitle": "From an individual discovery to more than 2,500 advertisers scaling with real data.",
    "about.timeline.discovery": "The Discovery",
    "about.timeline.discoveryDesc": "In December 2022, Eitor begins applying corporate analytics methods to the Brazilian affiliate market, identifying the data gap between clicks and conversions.",
    "about.timeline.method": "The market discovers the method",
    "about.timeline.methodDesc": "October 2023: Eitor publishes the first video explaining the method. Content goes viral and changes the level of Google Ads operations in Brazil.",
    "about.timeline.meeting": "Paulo meets Eitor",
    "about.timeline.meetingDesc": "January 2024: Paulo Furtado sees the video and proposes to Eitor to build the software that would systematize the method.",
    "about.timeline.launch": "Ratoeira Ads goes live",
    "about.timeline.launchDesc": "April 15, 2024: Ratoeira Ads goes live with the mission to democratize server-side tracking for the Brazilian market.",
    "about.timeline.expansion": "Ecosystem expansion",
    "about.timeline.expansionDesc": "Ratoeira Pages and Ratoeira Hub are launched, integrating page building and consolidated dashboard into the ecosystem.",
    "about.timeline.ai": "AI and new channels",
    "about.timeline.aiDesc": "The platform incorporates artificial intelligence and expands to Meta Ads, Native Ads, and new traffic sources.",

    // About Gallery
    "about.gallery.title": "The <span class='text-brand-primary'>team</span> behind the <span class='text-brand-primary'>platform</span>.",
    "about.gallery.subtitle": "A technical, direct team obsessed with the advertiser's problem. Ratoeira wasn't built in a meeting room — it was built by those who lived the problem from the inside.",
