    // About Platform CTA
    "about.platform.title": "We are the <span class='text-transparent bg-clip-text bg-gradient-to-r from-orange-600 to-amber-500'>definitive</span> ecosystem for scale.",
    "about.platform.description": "We designed <span class='whitespace-nowrap'>Ratoeira Hub</span> to annihilate budget waste and technical complexity. We offer a safe, fast, and comprehensive solution that combines surgical tracking and high-conversion pages in one place.",

    // About MVV
    "about.mvv.mission": "Mission",
    "about.mvv.missionDesc": "Democratize access to clean data and intelligent decisions in paid traffic, so any advertiser — from beginner to professional manager — can scale with predictability.",
    "about.mvv.vision": "Vision",
    "about.mvv.visionDesc": "Be the reference ecosystem in tracking and optimization of paid traffic for the Latin American market, impact 100,000 operations by 2027.",
    "about.mvv.values": "Values",
    "about.mvv.values.title1": "Change lives",
    "about.mvv.values.title2": "Customer is the reason",
    "about.mvv.values.title3": "Be the best at what we do",
    "about.mvv.values.title4": "The truth, always",
    "about.mvv.values.title5": "Innovate to survive",
    "about.mvv.values.item1": "Data before guesswork: every decision is backed by real data.",
    "about.mvv.values.item2": "Simplicity: advanced technology, simple use.",
    "about.mvv.values.item3": "Transparency: clear prices, no fine print.",
    "about.mvv.values.item4": "Constant evolution: the market changes, Ratoeira changes with it.",
    "about.mvv.values.item5": "Innovation is survival: the paid traffic world changes fast. Seeking new ways to solve the same problem isn't a differentiator — it's survival.",

    // About Founders
    "about.founders.founder1": "Eitor Guimarães",
    "about.founders.role1": "Co-founder & CEO",
    "about.founders.founder2": "Paulo Furtado",
    "about.founders.role2": "Co-founder & CTO",
    "about.founders.founder3": "Brayan Cicarone",
    "about.founders.role3": "Co-founder & Development Lead - Ratoeira Pages",
    "about.founders.header": "Three people. One real problem. One platform",
    "about.founders.headerSubtitle": "The minds behind the ecosystem revolutionizing paid traffic.",
    "about.founders.three": "Three",
    "about.founders.people": "people.",
    "about.founders.problem": "problem",
    "about.founders.real": "real.",
    "about.founders.solution": "platform",
    "about.founders.subtitle": "The minds behind the ecosystem revolutionizing paid traffic.",
    "about.founders.eitorDesc": "Graduated from UNICAMP, Eitor built his career in analytics and market intelligence — working at 3M and PepsiCo, where he led Business Intelligence and Data & Analytics teams for Latin America. In 2022, he brought that knowledge to paid traffic and pioneered, in Brazil, what the Google Ads affiliate market still didn't have: server-side tracking so Google Ads optimizes for actual buyers. The method changed the market's level — operations that stalled at just R$100 thousand scaled to over a million. In April 2024, together with Paulo, he turned the discovery into a product. Today he leads Ratoeira as CEO.",
    "about.founders.pauloDesc": "Graduated in systems analysis in 2012, Paulo spent over a decade building robust systems — including working at Localiza. In January 2024, he watched Eitor's video about tracking for Google Ads affiliates and saw the product that still didn't exist. He went straight to Instagram to propose the partnership. As CTO of Ratoeira, Paulo is responsible for the architecture that ensures ~100% tracking, real-time event processing, and API integrations with Google Ads, Meta, and AI platforms.",
    "about.founders.brayanDesc1": "Software architecture specialist with an MBA in Databases, Brayan built his career working on system development, software architecture, and digital products. In 2025, he began collaborating with Paulo and Eitor on the evolution of Ratoeira Ads, helping solve technical challenges and structure new solutions for the market.",
    "about.founders.brayanDesc2": "During this process, he saw the need for a platform that would simplify page creation and integrations for advertisers. From this vision, Ratoeira Pages was born. Today, he is responsible for the platform's architecture, AI integrations, and building the tools that drive the next phase of the Ratoeira ecosystem.",

