    "privacidade.pages.section10.p1": "In case of portability or data export request, pursuant to art. 18, V of the LGPD, RATOEIRA PAGES will make the data available in structured format within 30 (thirty) business days. The administrative cost of export may be charged to the user, limited to the equivalent of 1 (one) month of the current plan at the time of request, except in cases where gratuity is expressly required by applicable law.",
    "privacidade.pages.section11.title": "Changes to this Policy",
    "privacidade.pages.section11.p1": "RATOEIRA PAGES may change this Policy at any time, with the most recent version always available on this page. We recommend that the user consult it periodically. Substantial changes will be communicated by email or through a notice on the platform.",
    "privacidade.pages.section12.title": "Contact",
