    "cases.detail.operacao-alpha.name": "Operação Alpha",
    "cases.detail.operacao-alpha.role": "Infoproductors",
    "cases.detail.operacao-alpha.results.0": "+110% ROI",
    "cases.detail.operacao-alpha.results.1": "-40% Fraud",
    "cases.detail.operacao-alpha.results.2": "R$ 50k saved/month",
    "cases.detail.operacao-alpha.challenge": "Operação Alpha was suffering from a high rate of invalid clicks and bots that quickly consumed the daily budget on Google Ads. Additionally, the loss of conversion data from the standard pixel made it difficult to optimize campaigns, causing the CPA to be well above acceptable.",
    "cases.detail.operacao-alpha.solution": "By integrating Ratoeira Ads, the company started using server-side tracking, ensuring near-absolute accuracy in conversion events. Dynamic fraudulent IP blocking was also activated, protecting the budget and focusing only on real users.",
    "cases.detail.operacao-alpha.testimonial": "Ratoeira Hub not only saved our cash flow, but gave us the confidence needed to triple our investment in paid traffic without fear of losing money to bots.",
    "cases.detail.agencia-vortex.name": "Agência Vortex",
    "cases.detail.agencia-vortex.role": "Traffic Management",
    "cases.detail.agencia-vortex.results.0": "3x Faster",
    "cases.detail.agencia-vortex.results.1": "+25% Conversion",
    "cases.detail.agencia-vortex.results.2": "15 Clients Migrated",
    "cases.detail.agencia-vortex.challenge": "Managing landing pages for multiple clients was a logistical nightmare. Pages built on traditional platforms were slow to load, and advanced tracking setup took days from the technical team for each new launch.",
    "cases.detail.agencia-vortex.solution": "Agência Vortex migrated all operations to Ratoeira Pages. With conversion-focused templates and native tracking built into each new page, the team reduced deploy time from days to just a few hours.",
    "cases.detail.agencia-vortex.testimonial": "Our operation became much leaner and faster. Our clients felt the impact on conversion rate almost immediately due to the speed of the Flash Pages.",
    "cases.detail.metodo-escala.name": "Método Escala",
    "cases.detail.metodo-escala.role": "Top Player Advertiser",
    "cases.detail.metodo-escala.results.0": "~100% Tracking",
    "cases.detail.metodo-escala.results.1": "1-Click Setup",
    "cases.detail.metodo-escala.results.2": "Multiple 7-Figure",
    "cases.detail.metodo-escala.challenge": "The dependence on multiple disconnected tools caused constant discrepancies in reports. The advertiser didn't know exactly which ad generated real sales, preventing aggressive and safe scaling of offers on Meta and Google.",
    "cases.detail.metodo-escala.solution": "Adopting Ratoeira Hub unified page creation and server-side tracking. With a single dashboard displaying real ROI cross-referenced with approved sales, Método Escala started scaling with 100% accurate and reliable data.",
    "cases.detail.metodo-escala.testimonial": "I stopped operating blindly. Today, every cent invested is tracked, validated, and optimized to generate real profit. It was the best decision I ever made for my operation.",

