    // Ratoeira Ads - FeaturesAds
    "ratoeiraAds.features.title": "The end of guesswork in paid traffic.",
    "ratoeiraAds.features.subtitle": "Ratoeira Ads operates on 6 fronts to ensure you know exactly which Google Ads ad generated each cent of result — from click to sale.",
    "ratoeiraAds.features.serverSide.title": "Server-Side Tracking",
    "ratoeiraAds.features.serverSide.desc": "Your data no longer depends on cookies or the browser pixel. Ratoeira sends conversions directly to the Google Conversions API — server-side, with enriched sending. What the standard pixel loses 25% to 40% of the time, Ratoeira registers. More real conversions reaching Google Ads means algorithm optimizing for who actually buys.",
    "ratoeiraAds.features.ipBlocking.title": "Automatic IP Blocking",
    "ratoeiraAds.features.ipBlocking.desc": "Exclusive for Google Ads. You define the limit of clicks accepted per IP — Ratoeira automatically blocks whoever exceeds it. Competitors clicking on your ads, invalid traffic and bots are eliminated before consuming your budget. In most cases, what you save already pays for the entire plan.",
    "ratoeiraAds.features.conversions.title": "Optimized Conversions with Enriched Data",
    "ratoeiraAds.features.conversions.desc": "Ratoeira doesn't just send the event — it sends the enriched signal. With treated and protected primary data (such as email and phone) sent through the Conversions API, Google matches more sales to the click that generated them. Smart Bidding starts learning from real data, finds more people similar to your best buyers, and cost per acquisition drops while ROAS rises.",
    "ratoeiraAds.features.invisible.title": "Invisible Conversions Recovery",
    "ratoeiraAds.features.invisible.desc": "Advertisers who migrate to Ratoeira's server-side tracking recover on average 25% to 40% of conversions that were invisible. Each recovered sale is profit you had already generated — and didn't know. With more conversions reaching Google Ads, the algorithm optimizes faster and your campaign scales more safely.",
    "ratoeiraAds.features.realtime.title": "Real-Time Data",
    "ratoeiraAds.features.realtime.desc": "Google Ads takes time to consolidate conversions — and in that interval the algorithm may continue optimizing for the wrong audience. Ratoeira shows your integrated data — visits, leads and sales — faster than Google's own panel. You see what's working and act before the budget goes to the wrong place.",
    "ratoeiraAds.features.funnel.title": "Complete Funnel Visible",
    "ratoeiraAds.features.funnel.desc": "While other tools only show where clicks came from, Ratoeira shows where sales came from — with visits, leads and conversions integrated in one place. More real data reaching Google Ads means better audiences, smarter bids and a cost per acquisition that drops while profit rises.",
    "ratoeiraAds.features.manager.title": "Integrated Manager",
    "ratoeiraAds.features.manager.desc": "Control Google Ads campaigns, budgets, ads and audiences directly through Ratoeira. You pause, scale and adjust without switching tabs or opening Google Ads. Less friction, more execution speed and zero campaigns forgotten running in the red.",
    "ratoeiraAds.features.dashboard.title": "Consolidated Dashboard",
    "ratoeiraAds.features.dashboard.desc": "View everything in one place: impressions, clicks, CPC, CPL, ROAS, conversions and revenue — Google Ads metrics crossed with your sales platforms. No spreadsheets, no manual import. The dashboard you always wanted, but no tool alone delivered.",
    "ratoeiraAds.features.imagePlaceholder": "Space for Image/Mockup",

    // Ratoeira Ads - Hero
    "heroAds.badge": "~100% Tracking for <span class='whitespace-nowrap'>Google Ads</span>",
    "heroAds.title": "<span class='text-[#E6A600]'>~100%</span> tracking. <span class='text-[#E6A600]'>Automatic anti-fraud.</span> The data Google Ads doesn't deliver on its own.",
    "heroAds.subtitle": "For advertisers on <span class='whitespace-nowrap'>Google Ads</span> who need total clarity — not estimates. Every sale tracked, every fraud blocked, every decision made with real data.",

    // Ratoeira Ads - App Section
    "heroAds.app.title": "How about a trap in your <span class='text-brand-primary'>pocket</span>?",
    "heroAds.app.description": "With the <span class='whitespace-nowrap'>Ratoeira Ads</span> APP, you receive notifications and have access to your sales dashboard, all in real time.",
    "heroAds.app.notifications": "Real-time notifications",
    "heroAds.app.dashboard": "Sales dashboard",

    // Ratoeira Ads - CTA Radar
    "heroAds.cta.title": "Stop making decisions with <span class='text-brand-primary'>incomplete</span> data.",
    "heroAds.cta.description": "Configure <span class='text-brand-primary font-semibold whitespace-nowrap'>Ratoeira Ads</span> in minutes and discover the real ROI of your campaigns with ~100% tracking and automatic protection on <span class='whitespace-nowrap'>Google Ads</span>.",
    "heroAds.cta.button": "Sign Up Now — see plans",
    "heroAds.cta.tutorial": "Check out our full tutorial →",
    "heroAds.cta.radar.serverSide": "Server-Side",
    "heroAds.cta.radar.antiFraud": "Anti-Fraud",
