    // Hero
    "hero.title.sale": "Cada venta tiene un origen.",
    "hero.title.highlight": "Ratoeira te muestra cuál es.",
    "hero.subtitle": "Operaciones reales reportan aumento de ganancias de hasta 60% cuando comienzan a rastrear con datos reales. Cada clic, cada lead, cada venta — origen rastreado en Google y Meta, en tiempo real.",
    "hero.cta.signNow": "Suscribirse",
