    // Hub - CTA
    "hub.cta.title": "El <span style='background: linear-gradient(to right, #FFB800, #FF7E4A); -webkit-background-clip: text; background-clip: text; color: transparent;'>ecosistema completo</span> del tráfico pago. En un lugar.",
