    // Ratoeira Pages - Hero
    "heroPages.title": "<span class='text-orange-500'>Páginas rápidas</span>, integradas con tu <span class='text-orange-500'>tracking</span>. Listas en minutos.",
    "heroPages.subtitle": "Constructor visual con templates probados para conversión, Flash Pages ultra rápidas y generación por IA. Cada página ya nace con el tracking de Ratoeira Ads integrado — sin scripts sueltos, sin configuración manual.",

    // Ratoeira Pages - Features
    "heroPages.features.title": "Todo lo que necesitas para construir páginas que <span class='text-[#FF7E4A]'>convierten</span>.",
    "heroPages.features.subtitle": "Constructor, hospedaje y tracking en una sola plataforma — hecha para<br/>anunciantes que no tienen tiempo que perder con configuración.",

    "heroPages.features.flashPages.alt": "Flash Pages",
    "heroPages.features.flashPages.prefix": "Flash Pages:",
    "heroPages.features.flashPages.highlight": "Valida cualquier oferta en minutos.",
    "heroPages.features.flashPages.description": "Para anunciantes que necesitan probar rápido. Modelos preconfigurados para conversión — presell, cookie, edad, género, país y captcha. Textos, colores e imágenes editables sin una línea de código. Publica mientras la ventana de oportunidad aún está abierta.",

    "heroPages.features.templates.alt": "Templates Listos",
    "heroPages.features.templates.prefix": "Templates Listos:",
    "heroPages.features.templates.highlight": "Diseño Profesional al Tu Alcance",
    "heroPages.features.templates.description": "Adaptables a la identidad de tu marca en minutos.",

    "heroPages.features.dragDrop.alt": "Constructor Drag-and-Drop",
    "heroPages.features.dragDrop.prefix": "Editor Drag-and-Drop.",
    "heroPages.features.dragDrop.highlight": "Sin código.",
    "heroPages.features.dragDrop.description": "Monta tu página arrastrando bloques listos. Headings, imágenes, videos, formularios y CTAs — todo editable visualmente. Ninguna línea de código. Ningún desarrollador necesario. Publica y prueba en minutos.",

    "heroPages.features.ai.alt": "Presell Review con IA",
    "heroPages.features.ai.prefix": "Generación de Página por",
    "heroPages.features.ai.highlight": "IA",
    "heroPages.features.ai.description": "Describe el producto, la oferta y el público. La IA genera la estructura, los textos y el layout — tú ajustas, publicas y rastreas. Menos tiempo creando, más tiempo escalando.",

    "heroPages.features.tracking.alt": "Integración Ratoeira Ads",
    "heroPages.features.tracking.prefix": "Tracking Integrado Desde el Primer",
    "heroPages.features.tracking.highlight": "Clic",
    "heroPages.features.tracking.description": "Cada página creada en Ratoeira Pages ya nace con el script de Ratoeira Ads incrustado. Sin instalación manual. Sin riesgo de error. Tus datos de tracking y tus páginas hablan el mismo idioma — automáticamente.",

    "heroPages.features.hosting.alt": "Hospedaje Rápido Incluido",
    "heroPages.features.hosting.prefix": "Hospedaje Rápido",
    "heroPages.features.hosting.highlight": "Incluido",
    "heroPages.features.hosting.description": "Tus páginas quedan hospedadas en la infraestructura de Ratoeira con carga ultrarrápida. Sin servidor para contratar, sin CDN para configurar. Publica y empieza a rastrear inmediatamente.",

    "heroPages.features.cloner.alt": "Clonador de Páginas",
    "heroPages.features.cloner.prefix": "Clonador de Páginas:",
    "heroPages.features.cloner.highlight": "Replica Cualquier Página en Segundos.",
    "heroPages.features.cloner.description": "Pega la URL de la página que deseas replicar y el sistema clona la estructura, los estilos y los elementos automáticamente. Edita textos, imágenes y colores en el editor visual — sin necesidad de construir desde cero.",

    "heroPages.features.ab.alt": "Tests A/B",
    "heroPages.features.ab.prefix": "Tests A/B",
    "heroPages.features.ab.highlight": "Nativos en la Plataforma.",
    "heroPages.features.ab.description": "Crea variaciones de la misma página y distribuye el tráfico entre ellas directamente en Ratoeira Pages. Acompaña impresiones, conversiones, tasa de conversión e ingresos en tiempo real — sin herramientas externas.",

    "heroPages.features.cod.alt": "Sitios COD",
    "heroPages.features.cod.prefix": "Sitios COD",
    "heroPages.features.cod.highlight": "Listos para Escalar.",
    "heroPages.features.cod.description": "Estructura completa para operaciones Cash on Delivery con carga de archivos, validación de pedidos e integración nativa con el tracking. Sube tu sitio COD en minutos con toda la infraestructura lista.",

    "heroPages.features.nicheTemplates.alt": "Templates por Nicho",
    "heroPages.features.nicheTemplates.prefix": "Biblioteca de Templates por",
    "heroPages.features.nicheTemplates.highlight": "Nicho.",
    "heroPages.features.nicheTemplates.description": "Más de 100 templates organizados por categoría: Capture, Forms, Nutra, Presell, Review, Sell, Social Network y Thanks. Cada uno probado para conversión y listo para ser personalizado a tu oferta.",

    // Ratoeira Pages - CTA
    "heroPages.cta.title": "Tu <span class='text-orange-500'>próxima página</span> ya podría estar en el aire.",
    "heroPages.cta.description": "Deja de perder tiempo con herramientas que no se integran entre sí. Con <span class='text-[#FF7E4A] font-semibold'>Ratoeira Pages</span>, creas, publicas y ya empiezas a rastrear — todo en un lugar, todo conectado.",

