    // Benefits
    "benefits.title": "Beneficios",
    "benefits.subtitle": "Todo lo que necesitas para escalar",
    "benefits.card.label1": "Beneficio 1",
    "benefits.card.title1": "Deja de Perder Ventas Invisibles",
    "benefits.card.desc1": "Los anunciantes que migran al tracking server-side de Ratoeira recuperan en promedio 25% a 40% de conversiones que estaban invisibles. Cada venta recuperada es keuntungan que ya habías generado — y que el pixel estándar estaba ocultando de Google.",
    "benefits.card.label2": "Beneficio 2",
    "benefits.card.title2": "Protege Tu Presupuesto en Google Ads",
    "benefits.card.desc2": "Para quienes anuncian en Google Ads, Ratoeira bloquea automáticamente las IPs que hacen clic en tu anuncio sin intención de comprar — competidores, bots, tráfico inválido. En la mayoría de las operaciones, el ahorro con bloqueo ya cubre el costo del plan entero en el primer mes.",
    "benefits.card.label3": "Beneficio 3",
    "benefits.card.title3": "Publica Páginas en Minutos, No en Días",
    "benefits.card.desc3": "Templates listos y validados, Flash Pages que abren en menos de 1 segundo y tracking automático desde el primer clic. Tu página en el aire antes del próximo anuncio — y cada visita ya rastreada.",
    "benefits.card.label4": "Beneficio 4",
    "benefits.card.title4": "Toma Decisiones Con Datos Reales, No Intuición",
    "benefits.card.desc4": "Dashboard consolidado con métricas de Google Ads, Meta Ads y plataformas de venta en una sola pantalla. Ves cuál campaña escalar, cuál pausar — y actúas antes de que el algoritmo tome la decisión equivocada por ti.",
    "benefits.card.label5": "Beneficio 5",
    "benefits.card.title5": "Monitorea Desde Cualquier Lugar",
    "benefits.card.desc5": "App propia para iOS y Android. Notificación de venta en tiempo real, seguimiento de campañas y alertas de bloqueo — dondequiera que estés. La operación en la palma de tu mano.",
    "benefits.card.label6": "Beneficio 6",
    "benefits.card.title6": "Riesgo Cero",
