    "problem.header.title1": "Todo",
    "problem.header.title2": "lo que necesitas para dominar el",
    "problem.header.title3": "tráfico pagado",
    "problem.header.title4": "En un solo",
    "problem.header.title5": "lugar",
    "problem.header.subtitle": "Quien escala en Google y Meta no usa herramientas separadas. Usa un ecosistema donde tracking, páginas y datos hablan entre sí — y cada real invertido tiene un origen rastreado. Operaciones que migran al Hub reportan aumento de ganancias de hasta 60%.",
    "problem.header.note": "Conoce las herramientas o combina todo en el Hub para resultados máximos.",
    "problem.tabs.tracking": "Rastreo Inteligente",
    "problem.tabs.pages": "Páginas de Alta Conversión",
    "problem.tabs.ecossystem": "Ratoeira Hub",
    "problem.tracking.title": "Rastrea cada venta. Bloquea cada fraude. Decide más rápido.",
    "problem.tracking.description": "El pixel estándar desperdicia entre 25% y 40% de tus ventas — ocurren, pero Google nunca se entera. Ratoeira usa la tecnología de rastreo server-side más avanzada disponible hoy, con envío por browser y API simultáneamente, llegando a ~100% de conversiones rastreadas. El algoritmo comienza a optimizar para quienes realmente compran — y las ganancias suben.\n\nPara quienes anuncian en Google Ads: Ratoeira identifica y bloquea automáticamente los IPs que hacen clic en tu anuncio sin intención de comprar — competidores, bots, tráfico inválido. En la mayoría de las operaciones, lo que ahorras con bloqueo ya cubre el costo del plan entero en el primer mes.",
    "problem.tracking.highlight1": "Rastreo server-side con ~100% de conversiones rastreadas",
    "problem.tracking.highlight2": "Bloqueo automático de bots e IPs fraudulentos",
    "problem.tracking.highlight3": "Dashboard consolidado: Google Ads + Plataformas + Anti-Fraude",
    "problem.tracking.highlight4": "+60 plataformas de ventas conectadas",
    "problem.tracking.highlight5": "Notificaciones en tiempo real vía app y Telegram",
    "problem.tracking.alt": "Rastreo Inteligente",
    "problem.pages.title": "Construye páginas que venden en minutos. Sin código.",
    "problem.pages.description": "Ratoeira Pages es el constructor nativo del ecosistema. Templates listos y validados, Flash Pages que abren en menos de 1 segundo, creación por IA con 1 clic y hospedaje incluido. El diferencial: cada página ya nace con el tracking integrado — zero configuración, zero dato perdido entre la página y la campaña.",
    "problem.pages.highlight1": "Templates listos y probados para conversión",
    "problem.pages.highlight2": "Editor visual drag-and-drop (sin código)",
    "problem.pages.highlight3": "Flash Pages: páginas listas en segundos",
    "problem.pages.highlight4": "Generación de páginas por IA",
    "problem.pages.highlight5": "Hospedaje gratuito con SSL y dominios personalizados",
    "problem.pages.highlight6": "Integración nativa con Ratoeira Ads",
    "problem.pages.alt": "Páginas de Alta Conversión",
    "problem.ecossystem.title": "Ads + Pages juntos. Un login. Zero fricción.",
    "problem.ecossystem.description": "El verdadero poder de Ratoeira está en la integración nativa. Cuando Ads y Pages operan juntos, el tracking va más allá de lo que cada producto entrega por separado — porque el dato de la página alimenta la campaña en tiempo real. Mientras otros anunciantes operan con tres o más herramientas que no conversan entre sí, tú tienes todo consolidado en un único dashboard. Un login. Zero fricción. Resultado máximo.",
    "problem.ecossystem.highlight1": "Integración nativa Ads + Pages (sin configuración manual)",
