    // FAQ
    "faq.title": "Preguntas Frecuentes",
    "faq.subtitle": "Resuelve tus dudas",
    "faq.badge": "Centro de Ayuda",
    "faq.hero.title": "¿Cómo podemos <span class='text-brand-primary'>ayudar?</span>",
    "faq.hero.subtitle": "Encuentra respuestas rápidas a las dudas más comunes sobre Ratoeira Ads, nuestros planes e integraciones.",
    "faq.cta.title": "Horario de atención",
    "faq.cta.subtitle": "Nuestro equipo de especialistas está listo para ayudarte a escalar tus operaciones con seguridad.",
    "faq.cta.button": "Hablar con Soporte",
    "faq.q1.question": "¿Qué es Ratoeira Ads?",
    "faq.q1.answer": "Ratoeira Ads es la plataforma definitiva para escalar tus operaciones de tráfico pagado. Combina herramientas de tracking avanzado con protección contra fraudes en un único dashboard para garantizar máxima conversión.",
    "faq.q2.question": "¿Cómo funciona la protección contra fraudes?",
    "faq.q2.answer": "Nuestra tecnología utiliza algoritmos de inteligencia artificial y bloqueo de IPs dinámicos en tiempo real para identificar y bloquear tráfico de bots, clics fraudulentos y agentes malintencionados antes de que consuman tu presupuesto.",
    "faq.q3.question": "¿Puedo usar mis propios dominios?",
    "faq.q3.answer": "¡Sí! Dependiendo de tu plan, puedes conectar de 1 a ilimitados dominios personalizados, manteniendo la identidad visual de tu marca mientras aprovechas toda nuestra infraestructura de rastreo server-side.",
    "faq.q4.question": "¿Cuál es la diferencia entre los planes Mensual y Anual?",
    "faq.q4.answer": "Al optar por el plan Anual, además de garantizar el acceso ininterrumpido a la plataforma por 12 meses, obtienes un descuento exclusivo del 20% en el valor total. Todos los recursos del plan elegido permanecen iguales independientemente del ciclo de facturación.",
    "faq.q5.question": "¿Ratoeira Ads tiene período de prueba o garantía?",
    "faq.q5.answer": "Sí, estás protegido por nuestra garantía incondicional de 14 días (según el CDC). Si dentro de este período consideras que la plataforma no cumple con tus necesidades, solo solicita la cancelación y te devolvemos el 100% de tu dinero.",
    "faq.q6.question": "¿Necesito conocimiento técnico para configurar el tracking?",
    "faq.q6.answer": "¡No! Desarrollamos Ratoeira Ads con foco en la facilidad de uso. Nuestras integraciones nativas permiten conectar Ratoeira Ads a las principales fuentes de tráfico (Google, Meta, etc.) y pasarelas de pago con solo unos clics.",

