    // About
    "about.title": "Quiénes Somos",
    "about.subtitle": "Conoce Ratoeira Hub",

    // About Hero
    "about.hero.badge": "NUESTRA HISTORIA",
    "about.hero.title": "nació desde dentro del mercado. No desde fuera.",
    "about.hero.paragraph1": "En diciembre de 2022, Eitor Guimarães anunciaba como afiliado de Google Ads y aplicaba lo que sabía de análisis corporativo a un problema que el mercado brasileño aún no había resuelto: cómo capturar los datos del clic, cruzar con la conversión y devolver esa señal limpia al algoritmo de Google para que optimice para quienes realmente compran. Herramientas extranjeras hacían esto — y no funcionaban. Llegaban a costar R$1.000 por mes y aún así no entendían el ecosistema brasileño de afiliados.",
    "about.hero.paragraph2": "Eitor sistematizó el método y publicó un video en YouTube en octubre de 2023. Explotó. El mercado de afiliados de Google Ads cambió de nivel: operaciones que antes se estancaban en solo R$100 mil pasaron a escalar más de un millón. En enero de 2024, Paulo Furtado vio el video y fue directo al Instagram de Eitor para proponer construir el software. El 15 de abril de 2024, Ratoeira Ads entró al aire. Hoy, más de 2.500 anunciantes son suscriptores activos — y más de 10.000 ya pasaron por la plataforma.",

    // About Timeline
    "about.timeline.header": "Dos años. El <span class='text-[#FFB800]'>mercado</span> ya no es el <span class='text-[#FFB800]'>mismo</span>",
    "about.timeline.subtitle": "De un descubrimiento individual a más de 2.500 anunciantes que escalan con datos reales.",
    "about.timeline.discovery": "El Descubrimiento",
    "about.timeline.discoveryDesc": "En diciembre de 2022, Eitor comienza a aplicar métodos de análisis corporativo al mercado de afiliados brasileño, identificando la brecha de datos entre clics y conversiones.",
    "about.timeline.method": "El mercado descubre el método",
    "about.timeline.methodDesc": "Octubre de 2023: Eitor publica el primer video explicando el método. El contenido se viraliza y cambia el nivel de operaciones de Google Ads en Brasil.",
    "about.timeline.meeting": "Paulo conoce a Eitor",
    "about.timeline.meetingDesc": "Enero de 2024: Paulo Furtado ve el video y propone a Eitor construir el software que sistematizaría el método.",
    "about.timeline.launch": "Ratoeira Ads entra al aire",
    "about.timeline.launchDesc": "15 de abril de 2024: Ratoeira Ads entra al aire con la misión de democratizar el rastreo server-side para el mercado brasileño.",
