    // About Platform CTA
    "about.platform.title": "Somos el ecosistema <span class='text-transparent bg-clip-text bg-gradient-to-r from-orange-600 to-amber-500'>definitivo</span> para escalar.",
    "about.platform.description": "Diseñamos <span class='whitespace-nowrap'>Ratoeira Hub</span> para aniquilar el desperdicio de presupuesto y la complejidad técnica. Ofrecemos una solución segura, rápida y abrangente que une rastreo quirúrgico y páginas de altísima conversión en un único lugar.",

    // About MVV
    "about.mvv.mission": "Misión",
    "about.mvv.missionDesc": "Democratizar el acceso a datos limpios y decisiones inteligentes en tráfico pago, para que cualquier anunciante — del principiante al gerente profesional — pueda escalar con previsibilidad.",
    "about.mvv.vision": "Visión",
    "about.mvv.visionDesc": "Ser el ecosistema de referencia en rastreo y optimización de tráfico pago para el mercado latinoamericano, impactar 100.000 operaciones hasta 2027.",
    "about.mvv.values": "Valores",
    "about.mvv.values.title1": "Cambiar vidas",
    "about.mvv.values.title2": "El cliente es el motivo",
    "about.mvv.values.title3": "Ser los mejores en lo que hacemos",
    "about.mvv.values.title4": "La verdad, siempre",
    "about.mvv.values.title5": "Innovar para sobrevivir",
    "about.mvv.values.item1": "Datos antes que intuición: cada decisión está respaldada por datos reales.",
    "about.mvv.values.item2": "Simplicidad: tecnología avanzada, uso simple.",
    "about.mvv.values.item3": "Transparencia: precios claros, sin letra pequeña.",
    "about.mvv.values.item4": "Evolución constante: el mercado cambia, Ratoeira cambia con él.",
    "about.mvv.values.item5": "Innovar es sobrevivir: el mundo del tráfico pago cambia rápido. Buscar nuevas formas de resolver el mismo problema no es un diferencial — es supervivencia.",

    // About Founders
    "about.founders.founder1": "Eitor Guimarães",
    "about.founders.role1": "Co-fundador & CEO",
    "about.founders.founder2": "Paulo Furtado",
    "about.founders.role2": "Co-fundador & CTO",
    "about.founders.founder3": "Brayan Cicarone",
    "about.founders.role3": "Co-fundador & Líder de Desarrollo - Ratoeira Pages",
    "about.founders.header": "Tres personas. Un problema real. Una plataforma",
    "about.founders.headerSubtitle": "Las mentes detrás del ecosistema que está revolucionando el tráfico pago.",
    "about.founders.three": "Tres",
    "about.founders.people": "personas.",
    "about.founders.problem": "problema",
    "about.founders.real": "real.",
    "about.founders.solution": "plataforma",
    "about.founders.subtitle": "Las mentes detrás del ecosistema que está revolucionando el tráfico pago.",
    "about.founders.eitorDesc": "Egresado de UNICAMP, Eitor construyó su carrera en análisis e inteligencia de mercado — trabajando en 3M y PepsiCo, donde lideró equipos de Business Intelligence y Data & Analytics para América Latina. En 2022, llevó ese conocimiento al tráfico pago y sistematizó, de forma pionera en Brasil, lo que el mercado de afiliados de Google Ads aún no tenía: rastreo server-side para que Google Ads optimice para compradores reales. El método cambió el nivel del mercado — operaciones que se estancaban en solo R$100 mil pasaron a escalar más de un millón. En abril de 2024, junto con Paulo, transformó el descubrimiento en producto. Hoy lidera Ratoeira como CEO.",
    "about.founders.pauloDesc": "Egresado de análisis de sistemas en 2012, Paulo pasó más de una década construyendo sistemas robustos — incluyendo trabajo en Localiza. En enero de 2024, vio el video de Eitor sobre rastreo para afiliados de Google Ads y vio el producto que aún no existía. Fue directo al Instagram para proponer la sociedad. Como CTO de Ratoeira, Paulo es responsable de la arquitectura que garantiza ~100% de rastreo, procesamiento de eventos en tiempo real y las integraciones vía API con Google Ads, Meta y plataformas de IA.",
    "about.founders.brayanDesc1": "Especialista en arquitectura de software y MBA en Bases de Datos, Brayan construyó su trayectoria trabajando en desarrollo de sistemas, arquitectura de software y productos digitales. En 2025, comenzó a colaborar con Paulo y Eitor en la evolución de Ratoeira Ads, ayudando a resolver desafíos técnicos y a estructurar nuevas soluciones para el mercado.",
    "about.founders.brayanDesc2": "Al participar de este proceso, vio la necesidad de una plataforma que simplificara la creación de páginas e integraciones para anunciantes. De esta visión nació Ratoeira Pages. Hoy, es responsable de la arquitectura de la plataforma, de las integraciones con inteligencia artificial y de la construcción de las herramientas que impulsan la próxima fase del ecosistema Ratoeira.",

