    // Privacidade - Ads
    "privacidade.ads.title": "Política de Privacidad",
    "privacidade.ads.subtitle": "Ratoeira Ads",
    "privacidade.ads.description": "Tu seguridad y privacidad son nuestra prioridad.",
    "privacidade.ads.backToHome": "Volver al Inicio",
    "privacidade.ads.companyInfo": "Esta Política de Privacidad se aplica a todos los servicios prestados por RATOEIRA ADS DIGITAL MARKETING LTDA., persona jurídica de derecho privado, inscrita en el CNPJ bajo el nº 55.824.986/0001-06, ubicada en Alameda Rio Negro, 503, sala 2020, Alphaville, Barueri/SP, CEP: 06.454-000.",
    "privacidade.ads.section1.title": "Del Objeto",
    "privacidade.ads.section1.p1": "Con el objetivo de proteger tu privacidad, además de garantizar la libertad y el ejercicio de derechos del titular de los datos, RATOEIRA ADS presenta esta Política de Privacidad.",
    "privacidade.ads.section1.p2": "Este documento tiene como objetivo informar, de forma clara y objetiva, sobre cómo se realiza la recopilación, tratamiento y almacenamiento de datos personales esenciales para la prestación de sus servicios.",
    "privacidade.ads.section1.p3": "El titular de los datos personales declara estar enterado de esta Política y da expreso consentimiento para el Tratamiento de su Información Personal por RATOEIRA ADS.",
    "privacidade.ads.section1.p4": "Si no está de acuerdo con el Tratamiento de su Información Personal, en la forma prevista en esta Política, deberá abstenerse de utilizar los servicios de RATOEIRA ADS.",
    "privacidade.ads.section2.title": "Conceptos Importantes",
    "privacidade.ads.lgpd": "LGPD",
    "privacidade.ads.lgpdDesc": "Ley General de Protección de Datos (13.709/2018), que regula el tratamiento, protección y privacidad de Datos Personales en Brasil.",
    "privacidade.ads.dadosPessoais": "Datos Personales",
    "privacidade.ads.dadosPessoaisDesc": "Información que puede asociarse a una persona física identificada o identificable (nombre, CPF, correo, etc).",
    "privacidade.ads.tratamento": "Tratamiento",
    "privacidade.ads.tratamentoDesc": "Toda operación realizada con datos personales, desde la recopilación hasta la eliminación.",
    "privacidade.ads.titular": "Titular de Datos",
    "privacidade.ads.titularDesc": "Toda persona natural a quien se refieren los datos que son objeto de tratamiento.",
    "privacidade.ads.section3.title": "Datos Tratados y Finalidad",
    "privacidade.ads.section3.intro": "RATOEIRA ADS recopila y trata datos personales para garantizar la ejecución de los servicios, seguridad, prevención de fraudes y mejora de la experiencia:",
    "privacidade.ads.cadastrais": "Cadastrales",
    "privacidade.ads.cadastraisDesc": "Nombre completo, CPF/CNPJ, correo, teléfono, dirección y datos de pago.",
    "privacidade.ads.navegacao": "Navegación y Uso",
    "privacidade.ads.navegacaoDesc": "Datos de navegación, registros de acceso, patrones de uso de la plataforma, dirección IP, cookies e información técnica del dispositivo.",
    "privacidade.ads.financeiros": "Financieros",
    "privacidade.ads.financeirosDesc": "Datos bancarios y de tarjeta para procesamiento de pagos y reparto de comisiones.",
    "privacidade.ads.campanhas": "Campañas",
    "privacidade.ads.campanhasDesc": "Datos de campañas publicitarias, estrategias, informes y configuraciones de tracking ingresadas por el Usuario.",
    "privacidade.ads.suporte": "Soporte",
    "privacidade.ads.suporteDesc": "Información relacionada con la duda, solicitud o comunicación con nuestro equipo de soporte.",
    "privacidade.ads.section4.title": "Bases Legales (LGPD)",
    "privacidade.ads.section4.intro": "El tratamiento de datos personales realizado por RATOEIRA ADS observa integralmente la Ley nº 13.709/2018 (LGPD). Las bases legales aplicadas son:",
    "privacidade.ads.base1.title": "Ejecución de contrato (art. 7º, V)",
    "privacidade.ads.base1.desc": "Para datos necesarios para la prestación del servicio, tracking de campañas, protección contra fraudes y procesamiento de pagos.",
    "privacidade.ads.base2.title": "Interés legítimo (art. 7º, IX)",
    "privacidade.ads.base2.desc": "Para seguridad, monitoreo de uso, prevención de fraudes, bloqueo de clics inválidos y protección de la plataforma.",
    "privacidade.ads.base3.title": "Cumplimiento de obligación legal (art. 7º, II)",
    "privacidade.ads.base3.desc": "Cuando sea exigido por legislación aplicable, incluyendo el Marco Civil de Internet (Ley nº 12.965/2014).",
    "privacidade.ads.base4.title": "Consentimiento (art. 7º, I)",
    "privacidade.ads.base4.desc": "Cuando sea aplicable, para envío de comunicaciones de marketing, boletines y novedades sobre la plataforma.",
    "privacidade.ads.section5.title": "Compartimiento de Datos",
    "privacidade.ads.section5.intro": "RATOEIRA ADS no comercializa datos personales. Los datos pueden ser compartidos en las siguientes hipótesis:",
    "privacidade.ads.parceiros": "Socios y Proveedores",
    "privacidade.ads.parceirosDesc": "Para garantizar la prestación de los servicios contratados (procesamiento de pagos, alojamiento, servicios de correo, infraestructura de servidores), siempre exigiendo las mismas directrices de seguridad.",
    "privacidade.ads.autoridades": "Autoridades Competentes",
    "privacidade.ads.autoridadesDesc": "Cuando sea requerido por orden judicial o determinación de autoridad competente.",
    "privacidade.ads.operacoes": "Operaciones Societarias",
    "privacidade.ads.operacoesDesc": "En caso de transferencia de control, adquisición o fusión, garantizada la continuidad de las obligaciones de privacidad.",
    "privacidade.ads.anonimizados": "Datos Anonimizados",
    "privacidade.ads.anonimizadosDesc": "RATOEIRA ADS podrá utilizar datos anonimizados y agregados para fines de investigación, desarrollo de producto y estadísticas de mercado. Dichos datos no están sujetos a las restricciones de la LGPD, en los términos del art. 12 de dicha Ley.",
    "privacidade.ads.section6.title": "Almacenamiento, Seguridad y Plazos",
    "privacidade.ads.section6.p1": "La información se almacena en servidores seguros con encriptación, firewalls y medidas técnicas de protección. RATOEIRA ADS adopta medidas rigurosas contra pérdida, robo o acceso no autorizado.",
    "privacidade.ads.section6.p2": "Sin embargo, no se responsabiliza por filtraciones de información derivadas de ataques cibernéticos sofisticados, fallas de terceros o negligencia del propio usuario en la protección de sus accesos.",
    "privacidade.ads.section6.p3": "Los registros de log del sistema, incluyendo acciones de los usuarios y patrones de comportamiento en la plataforma, se mantendrán por plazo mínimo de 5 (cinco) años, contados a partir del registro, en conformidad con el Marco Civil de Internet (Ley nº 12.965/2014) y la LGPD, pudiendo ser utilizados como medio de prueba en cualquier procedimiento judicial, administrativo o arbitral.",
    "privacidade.ads.section6.p4": "Los datos de registro se mantienen mientras el usuario esté activo en la plataforma, pudiendo ser guardados por período adicional para cumplimiento de obligaciones legales.",
    "privacidade.ads.section7.title": "Cookies y Tecnologías de Tracking",
    "privacidade.ads.section7.intro": "RATOEIRA ADS utiliza cookies y tecnologías similares para mejorar la experiencia del usuario, analizar tráfico, recordar preferencias y personalizar contenido. Los tipos de cookies utilizados incluyen:",
    "privacidade.ads.cookies.essenciais": "Esenciales",
    "privacidade.ads.cookies.essenciaisDesc": "Necesarios para el funcionamiento básico de la plataforma y autenticación.",
    "privacidade.ads.cookies.analiticos": "Analíticos",
    "privacidade.ads.cookies.analiticosDesc": "Utilizados para entender cómo los usuarios interactúan con la plataforma y mejorar nuestros servicios.",
    "privacidade.ads.cookies_funcionais": "Funcionales",
