    "privacidade.ads.cookies.manage": "El usuario puede gestionar las preferencias de cookies directamente en la configuración del navegador.",
    "privacidade.ads.section8.title": "Sus Derechos (Art. 18 LGPD)",
    "privacidade.ads.section8.intro": "USTED, en su calidad de titular de datos, tiene derecho a solicitar en cualquier momento:",
