    "privacidade.ads.section9.title": "Portabilidad de Datos",
    "privacidade.ads.section9.p1": "En caso de solicitud de portabilidad o exportación de datos, en los términos del art. 18, V de la LGPD, RATOEIRA ADS disponibilizará los datos en formato estructurado en el plazo de hasta 30 (treinta) días hábiles. El costo administrativo de la exportación podrá ser cobrado al usuario, limitado al valor equivalente a 1 (un) mes del plan vigente al momento de la solicitud, excepto en las hipótesis en que la gratuidad sea expresamente exigida por la legislación aplicable.",
    "privacidade.ads.section10.title": "Alteraciones en esta Política",
    "privacidade.ads.section10.p1": "RATOEIRA ADS podrá alterar esta Política en cualquier momento, siendo que la versión más reciente estará siempre disponible en esta página. Recomendamos que el usuario la consulte periódicamente. Alteraciones sustanciales serán comunicadas por correo o por medio de aviso en la plataforma.",
