    // Cases detail por ID — alimenta /cases/[id]
    "cases.detail.operacao-alpha.name": "Operación Alpha",
    "cases.detail.operacao-alpha.role": "Infoproductores",
    "cases.detail.operacao-alpha.results.0": "+110% ROI",
    "cases.detail.operacao-alpha.results.1": "-40% Fraudes",
    "cases.detail.operacao-alpha.results.2": "R$ 50k ahorrados/mes",
    "cases.detail.operacao-alpha.challenge": "Operación Alpha sufría con una alta tasa de clics inválidos y bots que consumían rápidamente el presupuesto diario en Google Ads. Además, la pérdida de datos de conversión por el píxel estándar dificultaba la optimización de las campañas, causando que el CPA estuviera muy por encima de lo aceptable.",
    "cases.detail.operacao-alpha.solution": "Al integrar Ratoeira Ads, la empresa pasó a utilizar el tracking server-side, garantizando precisión casi absoluta en los eventos de conversión. El bloqueo dinámico de IPs fraudulentas también se activó, protegiendo el presupuesto y enfocándose solo en usuarios reales.",
    "cases.detail.operacao-alpha.testimonial": "Ratoeira Hub no solo salvó nuestra caja, sino que nos dio la confianza necesaria para triplicar nuestra inversión en tráfico pago sin miedo a perder dinero con bots.",
    "cases.detail.agencia-vortex.name": "Agencia Vortex",
    "cases.detail.agencia-vortex.role": "Gestión de Tráfico",
    "cases.detail.agencia-vortex.results.0": "3x Más Rápido",
    "cases.detail.agencia-vortex.results.1": "+25% Conversión",
    "cases.detail.agencia-vortex.results.2": "15 Clientes Migrados",
    "cases.detail.agencia-vortex.challenge": "Gestionar landing pages para múltiples clientes era una pesadilla logística. Las páginas desarrolladas en plataformas tradicionales tardaban en cargar, y la configuración de rastreo avanzado tomaba días del equipo técnico para cada nuevo lanzamiento.",
    "cases.detail.agencia-vortex.solution": "La Agencia Vortex migró todas sus operaciones a Ratoeira Pages. Con plantillas enfocadas en conversión y rastreo nativo ya integrado en cada nueva página, el equipo redujo el tiempo de deploy de días a solo unas horas.",
    "cases.detail.agencia-vortex.testimonial": "Nuestra operación quedó mucho más ágil y rápida. Nuestros clientes sintieron el impacto en la tasa de conversión casi inmediatamente debido a la velocidad de las Flash Pages.",
    "cases.detail.metodo-escala.name": "Método Escala",
    "cases.detail.metodo-escala.role": "Anunciante Top Player",
    "cases.detail.metodo-escala.results.0": "~100% Tracking",
    "cases.detail.metodo-escala.results.1": "Setup en 1 Clic",
    "cases.detail.metodo-escala.results.2": "Múltiples 7 Dígitos",
    "cases.detail.metodo-escala.challenge": "La dependencia de múltiples herramientas desconectadas causaba divergencias constantes en los informes. El anunciante no sabía exactamente qué anuncio generaba ventas reales, lo que impedía una escala agresiva y segura de las ofertas en Meta y Google.",
    "cases.detail.metodo-escala.solution": "La adopción de Ratoeira Hub unificó la creación de páginas y el tracking server-side. Con un único dashboard mostrando el ROI real cruzado con las ventas aprobadas, el Método Escala pasó a escalar con datos 100% precisos y confiables.",
    "cases.detail.metodo-escala.testimonial": "Dejé de operar a ciegas. Hoy, cada centavo invertido se rastrea, valida y optimiza para generar ganancia real. Fue la mejor decisión que he tomado para mi operación.",

