    // Ratoeira Ads - FeaturesAds
    "ratoeiraAds.features.title": "El fin del acierto en el tráfico pagado.",
    "ratoeiraAds.features.subtitle": "Ratoeira Ads actúa en 6 frentes para garantizar que sepas exactamente qué anuncio de Google Ads generó cada centavo de resultado — del clic a la venta.",
    "ratoeiraAds.features.serverSide.title": "Tracking Server-Side",
    "ratoeiraAds.features.serverSide.desc": "Tus datos ya no dependen de cookies o del pixel en el navegador. Ratoeira envía las conversiones directamente a la API de Conversiones de Google — server-side, con envío enriquecido. Lo que el pixel estándar pierde entre 25% y 40% de las veces, Ratoeira lo registra. Más conversiones reales llegando a Google Ads significa algoritmo optimizando para quienes realmente compran.",
    "ratoeiraAds.features.ipBlocking.title": "Bloqueo Automático de IP",
    "ratoeiraAds.features.ipBlocking.desc": "Exclusivo para Google Ads. Tú defines el límite de clics aceptados por IP — Ratoeira bloquea automáticamente a quien lo supere. Competidores que hacen clic en tus anuncios, tráfico inválido y bots se eliminan antes de consumir tu presupuesto. En la mayoría de los casos, lo que ahorras ya paga el plan entero.",
    "ratoeiraAds.features.conversions.title": "Conversiones Optimizadas con Datos Enriquecidos",
    "ratoeiraAds.features.conversions.desc": "Ratoeira no solo envía el evento — envía la señal enriquecida. Con datos primarios tratados y protegidos (como email y teléfono) enviados por la API de Conversiones, Google relaciona más ventas al clic que las generó. Smart Bidding empieza a aprender con datos reales, encuentra más personas similares a tus mejores compradores y el costo por adquisición cae mientras el ROAS sube.",
    "ratoeiraAds.features.invisible.title": "Recuperación de Conversiones Invisibles",
    "ratoeiraAds.features.invisible.desc": "Anunciantes que migran al tracking server-side de Ratoeira recuperan en promedio 25% a 40% de conversiones que estaban invisibles. Cada venta recuperada es ganancia que ya habías generado — y no sabías. Con más conversiones llegando a Google Ads, el algoritmo optimiza más rápido y tu campaña escala con más seguridad.",
    "ratoeiraAds.features.realtime.title": "Datos en Tiempo Real",
    "ratoeiraAds.features.realtime.desc": "Google Ads tarda en consolidar conversiones — y en ese intervalo el algoritmo puede seguir optimizando para el público equivocado. Ratoeira muestra tus datos integrados — visitas, leads y ventas — más rápido que el propio panel de Google. Ves lo que está funcionando y actúas antes de que el presupuesto vaya al lugar equivocado.",
    "ratoeiraAds.features.funnel.title": "Embudo Completo Visible",
    "ratoeiraAds.features.funnel.desc": "Mientras otras herramientas solo muestran de dónde vinieron los clics, Ratoeira muestra de dónde vinieron las ventas — con visitas, leads y conversiones integradas en un solo lugar. Más datos reales llegando a Google Ads significa públicos mejores, pujas más inteligentes y un costo por adquisición que cae mientras la ganancia sube.",
    "ratoeiraAds.features.manager.title": "Gestor Integrado",
    "ratoeiraAds.features.manager.desc": "Controla campañas, presupuestos, anuncios y públicos de Google Ads directamente desde Ratoeira. Pausas, escalas y ajustas sin necesidad de cambiar de pestaña ni abrir Google Ads. Menos fricción, más velocidad de ejecución y cero campañas olvidadas corriendo en rojo.",
    "ratoeiraAds.features.dashboard.title": "Dashboard Consolidado",
    "ratoeiraAds.features.dashboard.desc": "Visualiza todo en un solo lugar: impresiones, clics, CPC, CPL, ROAS, conversiones y receita — métricas de Google Ads cruzadas con tus plataformas de venta. Sin hojas de cálculo, sin importación manual. El dashboard que siempre quisiste tener, pero ninguna herramienta sola entregaba.",
    "ratoeiraAds.features.imagePlaceholder": "Espacio para Imagen/Mockup",

